window.FTA_TOUR = {"slug":"eno-slow-morning","title":"Loops for a Slow Morning","artist":"Brian Eno","bpm":60,"key":"","seconds":150.0,"group":"soundtrack","how":"Give a few short phrases loops of different lengths, none a multiple of another, then step back. The music is whatever their drifting phase happens to do.","trick":"Seven loops of 17.9 to 37.9 seconds. Their lengths share no common multiple inside the piece, so no moment ever repeats.","stops":[{"t":0,"label":"loops begin","text":"Felt piano and bells start, each on its own clock. Listen for notes that seem to answer each other. They don't know about each other."},{"t":18,"label":"first voice","text":"A voice enters on a 41-second loop, its vowel sliding from \"oo\" to \"oh\". The drone underneath breathes on 11, 13 and 17 second cycles."},{"t":61,"label":"all three voices","text":"All three voice loops are now running (41, 47 and 53 s). Every chord you hear from here on is a coincidence of timing."},{"t":136,"label":"last strike","text":"The last strike. The hall rings on while the piece fades."}],"checks":{"lufs":-17.0,"tp":-1.8,"clicks":0,"sha":"1C1E8C413D3000A9"},"gram":{"rows":72,"cols":1500,"lo":"C1","fps":10,"b64":""}};
